/* Mandatory rule for robust hidden element toggling */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #1c1427;
  --color-card: #2e2140;
  --color-crust: #e69c24;
  --color-accent: #f25f5c;
  --color-accent-dark: #b83330;
  --color-text: #fff6d6;
  --color-text-dim: #cca88b;
  --color-border: #000000;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: "Courier New", Courier, monospace, system-ui;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.app-container {
  width: 100%;
  max-width: 480px;
}

/* Pixel Card Styling with stepped block borders */
.pixel-card {
  background-color: var(--color-card);
  border: 4px solid var(--color-border);
  box-shadow:
    8px 8px 0px 0px #0e0717,
    inset -4px -4px 0px 0px #1a1226,
    inset 4px 4px 0px 0px #44325e;
  padding: 24px 20px;
}

.header {
  text-align: center;
  margin-bottom: 24px;
}

/* Pure CSS Pixel Pizza Icon */
.pixel-pizza-icon {
  width: 32px;
  height: 32px;
  margin: 0 auto 12px;
  background-color: var(--color-crust);
  box-shadow:
    0 -4px 0 var(--color-border),
    0 4px 0 var(--color-border),
    -4px 0 0 var(--color-border),
    4px 0 0 var(--color-border),
    -6px 6px 0 -2px var(--color-accent),
    4px -4px 0 -2px var(--color-accent),
    2px 4px 0 -1px #fff6d6;
}

.title {
  font-size: 26px;
  letter-spacing: 2px;
  color: var(--color-crust);
  text-shadow: 2px 2px 0 var(--color-border);
  margin-bottom: 4px;
}

.subtitle {
  color: var(--color-text-dim);
  font-size: 14px;
  letter-spacing: 1px;
}

.pixel-group {
  border: 3px solid var(--color-border);
  background: #251a35;
  padding: 14px;
  margin-bottom: 18px;
}

.group-title {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 8px;
  font-weight: bold;
  font-size: 16px;
  color: var(--color-crust);
}

.counter-badge {
  background: var(--color-border);
  color: var(--color-text);
  padding: 2px 6px;
  font-size: 14px;
}

/* Alert / Error Banner */
.error-banner {
  background: var(--color-accent);
  color: #ffffff;
  border: 2px solid var(--color-border);
  padding: 8px 12px;
  margin: 10px 0;
  font-weight: bold;
  font-size: 15px;
  text-align: center;
  letter-spacing: 1px;
  animation: pixelShake 0.25s linear;
}

@keyframes pixelShake {
  0%, 100% { transform: translate(0, 0); }
  25% { transform: translate(-3px, 0); }
  75% { transform: translate(3px, 0); }
}

/* Button-like selection grid */
.options-grid {
  display: grid;
  gap: 10px;
  margin-top: 10px;
}

.sizes-grid {
  grid-template-columns: repeat(3, 1fr);
}

.toppings-grid {
  grid-template-columns: repeat(2, 1fr);
}

@media (max-width: 400px) {
  .sizes-grid {
    grid-template-columns: 1fr;
  }
  .toppings-grid {
    grid-template-columns: 1fr;
  }
}

.pixel-radio-label,
.pixel-checkbox-label {
  position: relative;
  display: block;
  cursor: pointer;
}

.pixel-radio-label input,
.pixel-checkbox-label input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.pixel-button-face {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  background: #392a4e;
  border: 2px solid var(--color-border);
  box-shadow: 2px 2px 0px 0px var(--color-border);
  color: var(--color-text);
  padding: 8px;
  font-size: 14px;
  text-align: center;
  user-select: none;
  transition: background-color 0.1s ease;
}

.price-tag {
  font-size: 13px;
  color: var(--color-text-dim);
  margin-top: 2px;
}

/* Hover / Focus / Checked States */
.pixel-radio-label:hover .pixel-button-face,
.pixel-checkbox-label:hover .pixel-button-face {
  background: #473561;
}

.pixel-radio-label input:focus-visible + .pixel-button-face,
.pixel-checkbox-label input:focus-visible + .pixel-button-face {
  outline: 3px solid var(--color-crust);
  outline-offset: 1px;
}

.pixel-radio-label input:checked + .pixel-button-face,
.pixel-checkbox-label input:checked + .pixel-button-face {
  background: var(--color-crust);
  color: #1c1427;
  box-shadow: inset 2px 2px 0px 0px rgba(0, 0, 0, 0.4);
}

.pixel-radio-label input:checked + .pixel-button-face .price-tag {
  color: #4a340a;
  font-weight: bold;
}

/* Bottom Bar */
.price-action-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 20px;
  gap: 12px;
}

.total-display {
  display: flex;
  flex-direction: column;
}

.total-label {
  font-size: 13px;
  color: var(--color-text-dim);
  text-transform: uppercase;
}

.total-amount {
  font-size: 26px;
  font-weight: bold;
  color: var(--color-crust);
  text-shadow: 1px 1px 0 var(--color-border);
}

.pixel-cta-button,
.pixel-secondary-button {
  font-family: inherit;
  font-size: 16px;
  font-weight: bold;
  border: 3px solid var(--color-border);
  padding: 12px 20px;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.pixel-cta-button {
  background: var(--color-accent);
  color: #ffffff;
  box-shadow: 4px 4px 0 0 var(--color-border);
}

.pixel-cta-button:hover {
  background: #f77472;
}

.pixel-cta-button:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 0 var(--color-border);
}

.pixel-cta-button:focus-visible,
.pixel-secondary-button:focus-visible {
  outline: 3px solid #ffffff;
  outline-offset: 2px;
}

.pixel-secondary-button {
  background: #392a4e;
  color: var(--color-text);
  width: 100%;
  margin-top: 16px;
  box-shadow: 3px 3px 0 0 var(--color-border);
}

.pixel-secondary-button:hover {
  background: #473561;
}

.pixel-secondary-button:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 0 var(--color-border);
}

/* Order Summary Card */
.summary-card {
  margin-top: 20px;
  background: #251a35;
  border: 3px dashed var(--color-crust);
  padding: 18px;
}

.summary-title {
  font-size: 18px;
  color: var(--color-crust);
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.summary-divider {
  height: 2px;
  background: #392a4e;
  margin: 12px 0;
}

.summary-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 8px;
  font-size: 15px;
}

.summary-list {
  text-align: right;
  max-width: 60%;
  word-break: break-word;
  color: #ffffff;
}

.total-highlight {
  font-size: 18px;
  color: var(--color-crust);
}

.summary-status {
  margin-top: 12px;
  font-size: 13px;
  text-align: center;
  color: var(--color-text-dim);
  font-style: italic;
}

document.addEventListener('DOMContentLoaded', () => {
  const TOPPING_PRICE = 1.50;
  const MAX_TOPPINGS = 5;

  const form = document.getElementById('pizzaForm');
  const sizeRadios = document.querySelectorAll('input[name="pizzaSize"]');
  const toppingCheckboxes = document.querySelectorAll('input[name="toppings"]');
  const totalPriceEl = document.getElementById('totalPrice');
  const errorMessageEl = document.getElementById('errorMessage');
  const toppingCountBadge = document.getElementById('toppingCountBadge');

  const summaryCard = document.getElementById('summaryCard');
  const summarySize = document.getElementById('summarySize');
  const summaryToppingCount = document.getElementById('summaryToppingCount');
  const summaryToppings = document.getElementById('summaryToppings');
  const summaryTotal = document.getElementById('summaryTotal');
  const newOrderBtn = document.getElementById('newOrderBtn');

  let errorTimeout = null;

  function getSelectedSize() {
    const selected = document.querySelector('input[name="pizzaSize"]:checked');
    return {
      name: selected.value,
      price: parseFloat(selected.dataset.price)
    };
  }

  function getSelectedToppings() {
    return Array.from(toppingCheckboxes)
      .filter(cb => cb.checked)
      .map(cb => cb.value);
  }

  function calculateTotal() {
    const size = getSelectedSize();
    const toppings = getSelectedToppings();
    return size.price + (toppings.length * TOPPING_PRICE);
  }

  function updateUI() {
    const toppings = getSelectedToppings();
    const total = calculateTotal();

    totalPriceEl.textContent = `$${total.toFixed(2)}`;
    toppingCountBadge.textContent = `${toppings.length}/${MAX_TOPPINGS}`;
  }

  function showRefusalMessage() {
    errorMessageEl.hidden = false;
    if (errorTimeout) {
      clearTimeout(errorTimeout);
    }
    errorTimeout = setTimeout(() => {
      errorMessageEl.hidden = true;
    }, 2500);
  }

  // Handle size change
  sizeRadios.forEach(radio => {
    radio.addEventListener('change', updateUI);
  });

  // Handle topping selection with hard cap of 5
  toppingCheckboxes.forEach(checkbox => {
    checkbox.addEventListener('click', (e) => {
      const checkedCount = document.querySelectorAll('input[name="toppings"]:checked').length;

      if (checkbox.checked && checkedCount > MAX_TOPPINGS) {
        // Refuse 6th topping
        e.preventDefault();
        checkbox.checked = false;
        showRefusalMessage();
      } else {
        if (!errorMessageEl.hidden) {
          errorMessageEl.hidden = true;
        }
      }
      updateUI();
    });
  });

  // Handle Order form submission
  form.addEventListener('submit', (e) => {
    e.preventDefault();

    const size = getSelectedSize();
    const toppings = getSelectedToppings();
    const total = calculateTotal();

    summarySize.textContent = `${size.name} ($${size.price.toFixed(2)})`;
    summaryToppingCount.textContent = toppings.length;
    summaryToppings.textContent = toppings.length > 0 ? toppings.join(', ') : 'None';
    summaryTotal.textContent = `$${total.toFixed(2)}`;

    summaryCard.hidden = false;
    summaryCard.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  });

  // Modify order button
  newOrderBtn.addEventListener('click', () => {
    summaryCard.hidden = true;
    form.scrollIntoView({ behavior: 'smooth', block: 'start' });
  });

  // Initialize
  updateUI();
});
